+/** Theoretical use from sales vs actual consume movements per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoreticalByItem = new Map();
+  const dishesById = new Map((store.data.dishes ?? []).map((d) => [d.id, d]));
+  const recipesById = new Map(store.data.recipes.map((r) => [r.id, r]));
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = dishesById.get(s.dishId);
+    if (!dish) continue;
+    const recipe = recipesById.get(dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) {
+      if (n.qty <= 0) continue;
+      theoreticalByItem.set(n.itemId, (theoreticalByItem.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+
+  const actualByItem = new Map();
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actualByItem.set(itemId, (actualByItem.get(itemId) ?? 0) + m.qty);
+  }
+
+  const round3 = (n) => Math.round(n * 1000) / 1000 || 0;
+  return listItems(store)
+    .map((item) => {
+      const theoretical = round3(theoreticalByItem.get(item.id) ?? 0);
+      const actual = round3(actualByItem.get(item.id) ?? 0);
+      return {
+        itemId: item.id,
+        name: item.name,
+        unit: item.unit,
+        theoretical,
+        actual,
+        diff: round3(actual - theoretical),
+      };
+    })
+    .filter((row) => row.theoretical > 0 || row.actual > 0);
+}
