+++ b/src/io/sales-import.js
@@ -0,0 +1,100 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Already-imported tickets are skipped; any invalid row or stock shortfall
+// rejects the whole file and names the row.
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const [head = [], ...rawRows] = parseCsv(text);
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const rows = rawRows.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] ?? "").trim()])));
+
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    if (!/^\d+$/.test(r.dishId)) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dishId = Number(r.dishId);
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe ${dish.recipeId}` });
+    if (!/^\d+$/.test(r.qty)) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    const soldAt = r.soldAt.endsWith("Z") ? r.soldAt : new Date(r.soldAt).toISOString();
+    return { where, ticket: r.ticket, soldAt, dishId, qty, recipe };
+  });
+
+  const importedTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const fresh = clean.filter((c) => !importedTickets.has(c.ticket));
+  if (!fresh.length) return { tickets: 0, dishes: 0 };
+
+  const remaining = new Map();
+  const getRemaining = (itemId) => {
+    if (!remaining.has(itemId)) remaining.set(itemId, Math.round(onHand(store, itemId) * 1000) / 1000);
+    return remaining.get(itemId);
+  };
+  for (const row of fresh) {
+    row.needs = scaled(row.recipe, row.qty);
+    for (const n of row.needs) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      const available = getRemaining(n.itemId);
+      if (available < n.qty) {
+        throw new AppError("not_enough_stock", {
+          item: `${item.name} (${row.where})`,
+          available,
+          unit: item.unit,
+        });
+      }
+      remaining.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+  }
+
+  const snapshot = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    const tickets = new Set();
+    let dishes = 0;
+    for (const row of fresh) {
+      for (const n of row.needs) {
+        if (n.qty <= 0) continue;
+        try {
+          consume(store, n.itemId, n.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+        } catch (err) {
+          if (err instanceof AppError && err.code === "not_enough_stock") {
+            throw new AppError("not_enough_stock", {
+              ...err.params,
+              item: `${err.params.item} (${row.where})`,
+            });
+          }
+          throw err;
+        }
+      }
+      store.data.sales.push({
+        id: store.nextId("sale"),
+        ticket: row.ticket,
+        soldAt: row.soldAt,
+        dishId: row.dishId,
+        qty: row.qty,
+      });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    }
+    return { tickets: tickets.size, dishes };
+  } catch (err) {
+    store.data = snapshot;
+    throw err;
+  }
+}
